shellCommands.command:
/bin/bash -lc "cat > app/actions.ts <<'EOF'
'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATION_COOKIE = 'notifications_enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const notificationsEnabled = cookieStore.get(NOTIFICATION_COOKIE)?.value === 'on'

  cookieStore.set(NOTIFICATION_COOKIE, notificationsEnabled ? 'off' : 'on', {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
  })

  // Refresh the current route after the mutation without redirecting.
  refresh()
}
EOF"
